class MediaItem{final String sourceUrl,mediaUrl;final String? thumbnailUrl,title,author;const MediaItem({required this.sourceUrl,required this.mediaUrl,this.thumbnailUrl,this.title,this.author});Map<String,dynamic> toJson()=>{'sourceUrl':sourceUrl,'mediaUrl':mediaUrl,'thumbnailUrl':thumbnailUrl,'title':title,'author':author};factory MediaItem.fromJson(Map<String,dynamic> j)=>MediaItem(sourceUrl:j['sourceUrl'],mediaUrl:j['mediaUrl'],thumbnailUrl:j['thumbnailUrl'],title:j['title'],author:j['author']);}
